// Package billing is the Go port of App/app/billing.py quote and the
// monthly snapshot. Python is the oracle: testdata/quote_fixtures.json is
// generated by App/scripts/billing_fixtures.py and must match exactly.
package billing

import (
	"fmt"
	"math"
)

// Price holds whole-Kc amounts for one period, the same keys as Python.
type Price struct {
	Base       int `json:"base"`
	Max        int `json:"max"`
	TTLock     int `json:"ttlock"`
	Whitelabel int `json:"whitelabel"`
	Discount   int `json:"discount"`
	List       int `json:"list"`
	Total      int `json:"total"`
}

var plans = map[string]bool{"standard": true, "max": true}
var intervals = map[string]bool{"month": true, "year": true}

var base = map[string][3]int{"month": {149, 119, 99}, "year": {1190, 950, 790}}
var maxExtra = map[string][3]int{"month": {80, 59, 39}, "year": {718, 570, 370}}
var ttlock = map[string]int{"month": 40, "year": 480}
var whitelabel = map[string]int{"month": 590, "year": 5660}

const founderYear = 890

// band returns 0, 1 or 2 for the 1-based position of an apartment.
func band(index int) int {
	if index <= 4 {
		return 0
	}
	if index <= 9 {
		return 1
	}
	return 2
}

func graduated(count int, rates [3]int) int {
	sum := 0
	for i := 1; i <= count; i++ {
		sum += rates[band(i)]
	}
	return sum
}

// Quote prices one period. It mirrors billing.quote; discount rounds half to even.
func Quote(apartments int, plan, interval string, ttlockOn, whitelabelOn, founder bool, discountPercent int) (Price, error) {
	if !plans[plan] || !intervals[interval] {
		return Price{}, fmt.Errorf("unknown plan or interval: %s %s", plan, interval)
	}
	if discountPercent < 0 || discountPercent > 100 {
		return Price{}, fmt.Errorf("discount out of range: %d", discountPercent)
	}
	n := apartments
	if n < 0 {
		n = 0
	}
	var b int
	if founder && interval == "year" {
		b = founderYear * n
	} else {
		b = graduated(n, base[interval])
	}
	extra := 0
	if plan == "max" {
		extra = graduated(n, maxExtra[interval])
	}
	lock := 0
	if ttlockOn && plan != "max" {
		lock = ttlock[interval] * n
	}
	brand := 0
	if whitelabelOn {
		brand = whitelabel[interval]
	}
	list := b + extra + lock + brand
	discount := int(math.RoundToEven(float64(list*discountPercent) / 100))
	return Price{
		Base: b, Max: extra, TTLock: lock, Whitelabel: brand,
		Discount: discount, List: list, Total: list - discount,
	}, nil
}

// Monthly converts a period total to a monthly amount (Python _monthly).
func Monthly(total int, interval string) int {
	if interval == "month" {
		return total
	}
	return int(math.RoundToEven(float64(total) / 12))
}
